pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    BankCaller bc;

    function setUp() public {
        c = new C();
        bc = new BankCaller(address(c));
    }

    function testFuzz_property(address k) public {
        // the caller is a contract that qualifies as a Bank and starts with zero balance
        assertTrue(c.tokenBalance(address(bc)) == 0);
        // complete airDrop from the qualifying caller
        bc.doAirDrop();
        // General rule: for ANY address k, a completed airDrop leaves the caller's
        // balance at exactly 20 (credited by 20) and every other address's balance at 0.
        if (k == address(bc)) {
            assertTrue(c.tokenBalance(k) == 20, "caller must be credited exactly 20");
        } else {
            assertTrue(c.tokenBalance(k) == 0, "non-caller balance must stay 0");
        }
    }
}

contract BankCaller {
    C public target;

    constructor(address t) {
        target = C(t);
    }

    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    function doAirDrop() external {
        target.airDrop();
    }
}

