contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Adversarial counterparty: airDrop's msg.sender must be a contract
        // exposing supportsToken(); the fuzzer's seed picks the caller variant.
        GoodBank good = new GoodBank();
        address caller;
        if (seed % 2 == 0) {
            caller = address(good);
        } else {
            caller = address(uint160(uint256(keccak256(abi.encodePacked(seed)))));
            vm.assume(caller.code.length == 0);
