            caller = address(good);
        }
        vm.prank(caller);
        bool ok;
        try c.airDrop() { ok = true; } catch { ok = false; }
        // General rule: a legitimate Bank caller always receives the 20-token airdrop.
        assertTrue(ok && c.tokenBalance(caller) == 20);
    }
}

